/**
 * Porsche Design System Verification & Showcase Portal Engine
 * Trainable DS Compatible (v1.7.0)
 */

document.addEventListener("DOMContentLoaded", () => {
  initTheme();
  initNav();
  initSearch();
  loadTokens();
  loadComponents();
  initCopyHandlers();
});

// Toast notification
function showToast(message) {
  let toast = document.getElementById("portal-toast");
  if (!toast) {
    toast = document.createElement("div");
    toast.id = "portal-toast";
    toast.className = "portal-toast";
    document.body.appendChild(toast);
  }
  toast.textContent = message;
  toast.classList.add("show");
  setTimeout(() => toast.classList.remove("show"), 2200);
}

// ---------------------------------------------------------------------------
// Theme Management (Light / Dark Dual-Scheme)
// ---------------------------------------------------------------------------
function initTheme() {
  const toggleBtn = document.getElementById("theme-toggle-btn");
  const saved = localStorage.getItem("pds-theme") || "light";

  applyTheme(saved);

  if (toggleBtn) {
    toggleBtn.addEventListener("click", () => {
      const current = document.documentElement.getAttribute("data-theme") || "light";
      const next = current === "dark" ? "light" : "dark";
      applyTheme(next);
      localStorage.setItem("pds-theme", next);
      showToast(`Switched to ${next.toUpperCase()} mode`);
    });
  }
}

function applyTheme(theme) {
  document.documentElement.setAttribute("data-theme", theme);
  document.documentElement.style.colorScheme = theme;
  const toggleBtn = document.getElementById("theme-toggle-btn");
  if (toggleBtn) {
    toggleBtn.innerHTML = theme === "dark" ? "☀️ Light Mode" : "🌙 Dark Mode";
  }
}

// ---------------------------------------------------------------------------
// Navigation / Section Tabs
// ---------------------------------------------------------------------------
function initNav() {
  const navItems = document.querySelectorAll(".sidebar-nav .nav-item[data-target]");
  navItems.forEach((item) => {
    item.addEventListener("click", () => {
      const targetId = item.getAttribute("data-target");
      switchSection(targetId);

      navItems.forEach((n) => n.classList.remove("active"));
      item.classList.add("active");
    });
  });

  // Deep linking via hash
  if (window.location.hash) {
    const hashId = window.location.hash.replace("#", "");
    const matching = document.querySelector(`.sidebar-nav .nav-item[data-target="${hashId}"]`);
    if (matching) matching.click();
  }
}

function switchSection(sectionId) {
  document.querySelectorAll(".portal-section").forEach((sec) => {
    sec.style.display = "none";
  });
  const target = document.getElementById(sectionId);
  if (target) {
    target.style.display = "block";
    window.location.hash = sectionId;
    window.scrollTo({ top: 0, behavior: "smooth" });
  }
}

// ---------------------------------------------------------------------------
// Search Filter
// ---------------------------------------------------------------------------
function initSearch() {
  const searchInput = document.getElementById("global-search");
  if (!searchInput) return;

  searchInput.addEventListener("input", (e) => {
    const q = e.target.value.toLowerCase().trim();
    if (!q) {
      document.querySelectorAll(".comp-card, .color-swatch-card").forEach((el) => el.style.display = "");
      return;
    }

    // Filter component cards
    document.querySelectorAll(".comp-card").forEach((card) => {
      const text = card.textContent.toLowerCase();
      card.style.display = text.includes(q) ? "" : "none";
    });

    // Filter token cards
    document.querySelectorAll(".color-swatch-card").forEach((card) => {
      const text = card.textContent.toLowerCase();
      card.style.display = text.includes(q) ? "" : "none";
    });
  });
}

// ---------------------------------------------------------------------------
// Tokens Loader & Renderer
// ---------------------------------------------------------------------------
async function loadTokens() {
  let tokens = EMBEDDED_TOKENS;
  try {
    const res = await fetch("./tokens.json");
    if (res.ok) tokens = await res.json();
  } catch (err) {
    console.warn("Could not fetch tokens.json, using fallback", err);
  }

  renderColorTokens(tokens);
  renderTypographyTokens(tokens);
  renderSpacingTokens(tokens);
  renderRadiiTokens(tokens);
}

function renderColorTokens(tokens) {
  const grid = document.getElementById("colors-token-grid");
  if (!grid) return;

  const lightRoles = tokens?.sys?.color?.light || {
    canvas: { $value: "#ffffff", $description: "Light page background canvas" },
    surface: { $value: "#f1f1f4", $description: "Light primary surface container" },
    primary: { $value: "#010205", $description: "High-emphasis primary brand fill/text" },
    onPrimary: { $value: "#ffffff", $description: "Text and icon on primary fill" },
    frosted: { $value: "hsla(240, 5%, 70%, 0.148)", $description: "Standard frosted overlay" },
    frostedSoft: { $value: "rgba(143, 145, 163, 0.06)", $description: "Subtle frosted background" },
    frostedStrong: { $value: "rgba(100, 101, 114, 0.236)", $description: "Elevated frosted button/card fill" },
    contrastHigher: { $value: "rgba(21, 21, 25, 0.8)", $description: "Primary high-emphasis typography" },
    contrastHigh: { $value: "rgba(26, 26, 30, 0.7)", $description: "Body and heading text" },
    contrastMedium: { $value: "rgba(17, 17, 19, 0.6)", $description: "Secondary copy and labels" },
    contrastLow: { $value: "rgba(36, 36, 40, 0.5)", $description: "De-emphasized captions and placeholders" },
    contrastLower: { $value: "rgba(79, 80, 89, 0.324)", $description: "Borders, dividers, and disabled states" },
    info: { $value: "#1a44ea", $description: "Informational badges and alerts" },
    success: { $value: "#197e10", $description: "Success confirmations and checkmarks" },
    warning: { $value: "#ac5102", $description: "Warnings and cautions" },
    error: { $value: "#ba171f", $description: "Destructive actions and validation errors" },
    focus: { $value: "#1a44ea", $description: "Accessible focus ring" },
    backdrop: { $value: "rgba(36, 36, 40, 0.5)", $description: "Modal and flyout scrim backdrop" }
  };

  const darkRoles = tokens?.sys?.color?.dark || {};

  grid.innerHTML = "";

  Object.entries(lightRoles).forEach(([role, def]) => {
    const lightVal = def.$value;
    const darkVal = darkRoles[role]?.$value || lightVal;
    const cssVar = `--p-color-${kebabCase(role)}`;

    const card = document.createElement("div");
    card.className = "color-swatch-card";
    card.innerHTML = `
      <div class="swatch-preview" style="background: var(${cssVar}, ${lightVal});">
        <span style="font-size:0.7rem; font-weight:700; padding:2px 6px; border-radius:4px; background:rgba(0,0,0,0.6); color:#fff;">
          var(${cssVar})
        </span>
      </div>
      <div class="swatch-info">
        <div class="token-name">${cssVar}</div>
        <div class="token-value">Light: ${lightVal}</div>
        <div class="token-value">Dark: ${darkVal}</div>
        <div class="token-desc">${def.$description || ""}</div>
      </div>
    `;

    card.addEventListener("click", () => {
      navigator.clipboard.writeText(`var(${cssVar})`);
      showToast(`Copied ${cssVar}`);
    });

    grid.appendChild(card);
  });
}

function renderTypographyTokens(tokens) {
  const tbody = document.getElementById("typescale-tbody");
  if (!tbody) return;

  const tiers = [
    { tier: "5xl", size: "clamp(2.28rem, 5.2vw + 1.24rem, 7.48rem)", weight: "700", usage: "Massive stage splash title" },
    { tier: "4xl", size: "clamp(2.03rem, 3.58vw + 1.31rem, 5.61rem)", weight: "700", usage: "Hero display title" },
    { tier: "3xl", size: "clamp(1.8rem, 2.41vw + 1.32rem, 4.21rem)", weight: "600", usage: "Main page headline" },
    { tier: "2xl", size: "clamp(1.6rem, 1.56vw + 1.29rem, 3.16rem)", weight: "600", usage: "Major section title" },
    { tier: "xl", size: "clamp(1.42rem, 0.94vw + 1.23rem, 2.37rem)", weight: "600", usage: "Section heading" },
    { tier: "lg", size: "clamp(1.27rem, 0.51vw + 1.16rem, 1.78rem)", weight: "600", usage: "Card / component title" },
    { tier: "md", size: "clamp(1.13rem, 0.21vw + 1.08rem, 1.33rem)", weight: "600", usage: "Subheadings & lead body" },
    { tier: "sm", size: "1rem (16px)", weight: "400", usage: "Standard interface copy" },
    { tier: "xs", size: "0.875rem (14px)", weight: "400", usage: "Secondary captions & labels" },
    { tier: "2xs", size: "0.75rem (12px)", weight: "400", usage: "Legal text, consumption data" }
  ];

  tbody.innerHTML = "";
  tiers.forEach((t) => {
    const tr = document.createElement("tr");
    tr.innerHTML = `
      <td><code>sys.typescale.${t.tier}</code></td>
      <td style="font-family:monospace; font-size:0.8rem;">${t.size}</td>
      <td>${t.weight}</td>
      <td style="font-size:0.85rem; color:var(--p-color-contrast-medium);">${t.usage}</td>
      <td>
        <span style="font-size: var(--p-typescale-${t.tier}, 1rem); font-weight:${t.weight}; line-height:1.2; display:block;">
          Porsche Driven
        </span>
      </td>
    `;
    tbody.appendChild(tr);
  });
}

function renderSpacingTokens() {
  const container = document.getElementById("spacing-visualizer");
  if (!container) return;

  const staticTokens = [
    { name: "2xs", value: "1px" },
    { name: "xs", value: "4px" },
    { name: "sm", value: "8px" },
    { name: "md", value: "16px" },
    { name: "lg", value: "32px" },
    { name: "xl", value: "48px" },
    { name: "2xl", value: "80px" }
  ];

  container.innerHTML = "";
  staticTokens.forEach((s) => {
    const item = document.createElement("div");
    item.className = "spacing-item";
    item.innerHTML = `
      <div class="spacing-box" style="width:${s.value}; height:${s.value}; min-width:4px; min-height:4px;" title="--p-spacing-static-${s.name}: ${s.value}"></div>
      <div class="spacing-label">${s.name}<br/>${s.value}</div>
    `;
    item.addEventListener("click", () => {
      navigator.clipboard.writeText(`var(--p-spacing-static-${s.name})`);
      showToast(`Copied --p-spacing-static-${s.name}`);
    });
    container.appendChild(item);
  });
}

function renderRadiiTokens() {
  const container = document.getElementById("radii-visualizer");
  if (!container) return;

  const radii = [
    { name: "xs", value: "2px" },
    { name: "sm", value: "4px" },
    { name: "md", value: "6px" },
    { name: "lg", value: "8px" },
    { name: "xl", value: "12px" },
    { name: "2xl", value: "16px" },
    { name: "3xl", value: "24px" },
    { name: "4xl", value: "32px" },
    { name: "full", value: "9999px" }
  ];

  container.innerHTML = "";
  radii.forEach((r) => {
    const item = document.createElement("div");
    item.style.cssText = `
      display:flex; flex-direction:column; align-items:center; gap:0.5rem; cursor:pointer;
    `;
    item.innerHTML = `
      <div style="width:60px; height:60px; background:var(--p-color-surface); border:2px solid var(--p-color-primary); border-radius:var(--p-radius-${r.name}); display:flex; align-items:center; justify-content:center; font-size:0.75rem; font-weight:700;">
        ${r.name}
      </div>
      <span style="font-size:0.75rem; font-family:monospace; color:var(--p-color-contrast-medium);">${r.value}</span>
    `;
    item.addEventListener("click", () => {
      navigator.clipboard.writeText(`var(--p-radius-${r.name})`);
      showToast(`Copied --p-radius-${r.name}`);
    });
    container.appendChild(item);
  });
}

// ---------------------------------------------------------------------------
// Components Catalog & Demos
// ---------------------------------------------------------------------------
let allComponentsData = {};

async function loadComponents() {
  try {
    const res = await fetch("./components.json");
    if (res.ok) {
      const data = await res.json();
      allComponentsData = data.components || EMBEDDED_COMPONENTS;
      renderComponentCards("all");
      initComponentFilters();
    }
  } catch (err) {
    console.warn("Using embedded components fallback", err); allComponentsData = EMBEDDED_COMPONENTS; renderComponentCards("all"); initComponentFilters();
  }
}

function initComponentFilters() {
  const chips = document.querySelectorAll(".components-filter-bar .filter-chip");
  chips.forEach((chip) => {
    chip.addEventListener("click", () => {
      chips.forEach((c) => c.classList.remove("active"));
      chip.classList.add("active");
      const family = chip.getAttribute("data-family") || "all";
      renderComponentCards(family);
    });
  });
}

function renderComponentCards(filterFamily) {
  const grid = document.getElementById("components-gallery-grid");
  if (!grid) return;

  const entries = Object.entries(allComponentsData);
  const filtered = filterFamily === "all"
    ? entries
    : entries.filter(([_, comp]) => comp.family === filterFamily);

  grid.innerHTML = "";

  if (filtered.length === 0) {
    grid.innerHTML = `<p style="color:var(--p-color-contrast-medium)">No components found in family "${filterFamily}".</p>`;
    return;
  }

  filtered.forEach(([name, comp]) => {
    const card = document.createElement("div");
    card.className = "comp-card";

    const touchTarget = comp.anatomy?.container?.minTouchTarget || "48px (enforced)";
    const exampleSnippet = comp.examples?.[0] || `<${comp.tag} />`;

    card.innerHTML = `
      <div class="comp-card-header">
        <span class="comp-tag">&lt;${comp.tag}&gt;</span>
        <span class="comp-family-badge">${comp.family}</span>
      </div>
      <div class="comp-preview-area">
        ${renderInteractiveComponent(comp.tag, comp)}
      </div>
      <div class="comp-details">
        <div class="comp-desc">${comp.description}</div>
        <div class="comp-meta-row">
          <span>🎯 Touch target: <strong>${touchTarget}</strong></span>
          <span>⚡ Family: <strong>${comp.family}</strong></span>
        </div>
        <pre class="comp-code-snippet"><code>${escapeHtml(exampleSnippet)}</code></pre>
        <button type="button" class="btn-copy-code" data-copy="${escapeAttr(exampleSnippet)}">
          📋 Copy HTML Snippet
        </button>
      </div>
    `;

    grid.appendChild(card);
  });

  initCopyHandlers();
}

function renderInteractiveComponent(tag, comp) {
  switch (tag) {
    case "p-button":
      return `
        <button class="porsche-btn-primary" onclick="showToast('Primary button clicked')">
          Configure now
        </button>
        <button class="porsche-btn-secondary" onclick="showToast('Secondary button clicked')">
          Explore models
        </button>
      `;
    case "p-button-pure":
      return `
        <button class="porsche-btn-pure" onclick="showToast('Pure button clicked')">
          Technical specifications &rarr;
        </button>
      `;
    case "p-link":
      return `
        <a href="#templates" class="porsche-btn-primary" style="text-decoration:none;">
          Discover the 911
        </a>
      `;
    case "p-link-pure":
      return `
        <a href="#templates" class="porsche-btn-pure" style="text-decoration:none;">
          View dealership inventory &rarr;
        </a>
      `;
    case "p-heading":
      return `
        <h2 style="font-size:var(--p-typescale-xl); font-weight:600; color:var(--p-color-primary);">
          Find your dream Porsche.
        </h2>
      `;
    case "p-display":
      return `
        <h1 style="font-size:var(--p-typescale-3xl); font-weight:700; color:var(--p-color-primary); letter-spacing:-0.03em;">
          Cayenne Electric.
        </h1>
      `;
    case "p-text":
      return `
        <div style="display:flex; flex-direction:column; gap:0.25rem;">
          <p style="font-size:var(--p-typescale-sm); color:var(--p-color-contrast-high);">
            Standard body text rendering clean typography.
          </p>
          <p style="font-size:var(--p-typescale-2xs); color:var(--p-color-contrast-low);">
            Combined electrical consumption: 22.0 – 20.0 kWh/100 km (WLTP).
          </p>
        </div>
      `;
    case "p-tag":
      return `
        <div style="display:flex; gap:0.5rem; flex-wrap:wrap;">
          <span class="porsche-tag">Petrol</span>
          <span class="porsche-tag" style="background:var(--p-color-primary); color:var(--p-color-canvas);">Electric</span>
          <span class="porsche-tag">Hybrid</span>
        </div>
      `;
    case "p-tag-dismissible":
      return `
        <div class="porsche-tag" style="cursor:pointer;" onclick="this.style.display='none'; showToast('Tag dismissed');">
          Model: 911 GT3 RS &times;
        </div>
      `;
    case "p-input-search":
      return `
        <div style="display:flex; align-items:center; gap:0.5rem; background:var(--p-color-surface); border:1px solid var(--p-color-contrast-lower); border-radius:var(--p-radius-md); padding:0.6rem 1rem; width:100%; max-width:320px;">
          <span>🔍</span>
          <input type="text" placeholder="Enter postal code or city" style="border:none; background:transparent; width:100%; outline:none; font-family:inherit; color:var(--p-color-primary);" />
        </div>
      `;
    case "p-text-field":
      return `
        <div style="display:flex; flex-direction:column; gap:0.35rem; width:100%; max-width:300px;">
          <label style="font-size:0.8rem; font-weight:600; color:var(--p-color-contrast-high);">Full name</label>
          <input type="text" placeholder="Dr. Ferdinand Porsche" style="padding:0.6rem 0.8rem; border:1px solid var(--p-color-contrast-lower); border-radius:var(--p-radius-md); background:var(--p-color-surface); font-family:inherit; color:var(--p-color-primary); outline:none;" />
        </div>
      `;
    case "p-checkbox":
      return `
        <label style="display:flex; align-items:center; gap:0.6rem; cursor:pointer; min-height:48px;">
          <input type="checkbox" checked style="width:18px; height:18px; accent-color:var(--p-color-primary);" />
          <span style="font-size:0.9rem;">I agree to the privacy policy</span>
        </label>
      `;
    case "p-radio-button":
      return `
        <div style="display:flex; gap:1rem;">
          <label style="display:flex; align-items:center; gap:0.4rem; cursor:pointer; min-height:48px;">
            <input type="radio" name="demo-radio" checked style="accent-color:var(--p-color-primary);" />
            <span>PDK</span>
          </label>
          <label style="display:flex; align-items:center; gap:0.4rem; cursor:pointer; min-height:48px;">
            <input type="radio" name="demo-radio" style="accent-color:var(--p-color-primary);" />
            <span>Manual</span>
          </label>
        </div>
      `;
    case "p-switch":
      return `
        <label style="display:flex; align-items:center; gap:0.75rem; cursor:pointer; min-height:48px;">
          <input type="checkbox" checked style="width:24px; height:16px; accent-color:var(--p-color-primary);" />
          <span style="font-size:0.9rem; font-weight:500;">Sport exhaust system</span>
        </label>
      `;
    case "p-segmented-control":
      return `
        <div style="display:inline-flex; background:var(--p-color-surface); border:1px solid var(--p-color-contrast-lower); border-radius:var(--p-radius-full); padding:3px;">
          <button style="padding:6px 16px; border-radius:var(--p-radius-full); border:none; background:var(--p-color-primary); color:var(--p-color-canvas); font-weight:600; cursor:pointer;">Grid</button>
          <button style="padding:6px 16px; border-radius:var(--p-radius-full); border:none; background:transparent; color:var(--p-color-contrast-high); cursor:pointer;">List</button>
        </div>
      `;
    case "p-model-signature":
      return `
        <div style="display:flex; gap:1.5rem; align-items:center; flex-wrap:wrap;">
          <span class="porsche-signature">911</span>
          <span class="porsche-signature">Taycan</span>
          <span class="porsche-signature">Cayenne</span>
          <span class="porsche-signature">Panamera</span>
        </div>
      `;
    case "p-wordmark":
      return `
        <span style="font-family:'Porsche Next', sans-serif; font-size:1.6rem; font-weight:700; letter-spacing:0.35em; color:var(--p-color-primary); text-transform:uppercase;">
          PORSCHE
        </span>
      `;
    case "p-crest":
      return `
        <div style="width:36px; height:48px; background:#010205; border-radius:6px 6px 18px 18px; border:2px solid #b28938; display:flex; align-items:center; justify-content:center; color:#b28938; font-weight:bold; font-size:0.75rem; box-shadow:0 3px 6px rgba(0,0,0,0.3);">
          P
        </div>
      `;
    case "p-spinner":
      return `
        <div style="width:32px; height:32px; border:3px solid var(--p-color-contrast-lower); border-top-color:var(--p-color-primary); border-radius:50%; animation:pds-spin 0.8s linear infinite;"></div>
        <style>@keyframes pds-spin { to { transform: rotate(360deg); } }</style>
      `;
    case "p-banner":
      return `
        <div style="width:100%; padding:0.75rem 1rem; background:var(--p-color-frosted-strong); border-radius:var(--p-radius-md); border-inline-start:4px solid var(--p-color-info); display:flex; align-items:center; justify-content:space-between;">
          <span style="font-size:0.85rem; font-weight:500;">⚡ World Premiere: The new electric Cayenne.</span>
          <a href="#" style="font-size:0.8rem; color:var(--p-color-info); font-weight:600;">Watch live</a>
        </div>
      `;
    case "p-inline-notification":
      return `
        <div style="width:100%; padding:0.75rem 1rem; background:var(--p-color-surface); border:1px solid var(--p-color-contrast-lower); border-radius:var(--p-radius-lg); display:flex; gap:0.75rem; align-items:center;">
          <span style="color:var(--p-color-warning); font-size:1.2rem;">⚠️</span>
          <div style="font-size:0.82rem;">
            <strong>Configuration saved:</strong> You can resume your 911 build at any authorized dealer.
          </div>
        </div>
      `;
    case "p-accordion":
      return `
        <details style="width:100%; border:1px solid var(--p-color-contrast-lower); border-radius:var(--p-radius-md); padding:0.75rem; background:var(--p-color-surface);">
          <summary style="font-weight:600; cursor:pointer;">Performance & Dimensions</summary>
          <div style="padding-top:0.5rem; font-size:0.85rem; color:var(--p-color-contrast-medium);">
            Top speed: 312 km/h | 0-100 km/h in 3.4 s | Max Power: 380 kW (517 PS)
          </div>
        </details>
      `;
    case "p-link-tile":
      return `
        <div style="width:100%; max-width:280px; height:160px; background:linear-gradient(180deg, rgba(0,0,0,0.1), rgba(0,0,0,0.85)), #19191a; border-radius:var(--p-radius-xl); padding:1rem; display:flex; flex-direction:column; justify-content:flex-end; color:#fff;">
          <span style="font-weight:700; font-size:1.1rem;">Explore 911 Dakar</span>
          <span style="font-size:0.78rem; opacity:0.8;">Rough roads, limitless spirit</span>
        </div>
      `;
    default:
      return `
        <div style="padding:0.75rem 1rem; background:var(--p-color-surface); border-radius:var(--p-radius-md); font-family:monospace; font-size:0.85rem;">
          &lt;${tag}&gt; Active Prototype Contract
        </div>
      `;
  }
}

// ---------------------------------------------------------------------------
// Copy Handlers & Utilities
// ---------------------------------------------------------------------------
function initCopyHandlers() {
  document.querySelectorAll("[data-copy]").forEach((btn) => {
    btn.onclick = () => {
      const text = btn.getAttribute("data-copy");
      if (text) {
        navigator.clipboard.writeText(text);
        showToast("Snippet copied to clipboard!");
      }
    };
  });
}

function kebabCase(str) {
  return str.replace(/([a-z])([A-Z])/g, "$1-$2").toLowerCase();
}

function escapeHtml(str) {
  return str.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
}

function escapeAttr(str) {
  return str.replace(/"/g, "&quot;");
}
